       items_json = $ann_items$[{"tag": "完善", "date": "2026-11-14", "title": "知识库讲义全量精修落地：排版配色对齐、配图矢量重绘与搜索直练升级", "desc": "完成全部 232 篇三级讲义跨科错位清理与 2027 教材/真题同步，补充 C 语言/数据结构公式与源码实测校验；重绘 8 张高清无水印矢量配图（含排序查找过程与 UML 关系/顺序图）；统一红/绿/黄/灰四色重点徽章与注意事项卡配色；新增全库检索关键词居中摘要与相关性排序，讲义每个考点卡片右上角新增「专练本考点」直达入口。"}, {"tag": "重磅", "date": "2026-11-11", "desc": "覆盖考纲全部 232 个三级考点（理论 155 篇、技能 77 篇），每目末尾统一配置「考向复习提示」（考向脉络与背诵要点）与「高频易错陷阱」（历年真题常见失分点）。卡片采用胶囊式版式与三色标记，章节考情与正文分离置顶，便于集中复习。", "title": "全考纲 232 篇讲义尾部上线「复习提示」与「易错陷阱」"}, {"tag": "升级", "date": "2026-11-10", "desc": "两本复习教程 PDF（理论 135 页、操作技能 168 页）正文、红/绿/黄三色重点标记、18 张表格与 431 张经旋转校正并去水印的高清配图已完整收录，并在每节末尾补充真题独有要点。刷题解析、错题本、收藏夹与学习报告已全部切换至新版 232 个考纲三级讲义节点。", "title": "知识库二期全量升级，题目关联全部切至新版讲义"}, {"tag": "部署", "date": "2026-11-02", "desc": "站点部署于阿里云杭州节点，域名已完成 ICP 备案与公安联网备案（苏公网安备32132402000835号）。页面打开与切题响应为毫秒级；无需安装客户端，手机浏览器可直接使用。", "title": "部署于阿里云杭州节点，已完成备案"}]$ann_items$::jsonb,
       history_json = $ann_hist$[{"date": "2026-11-14", "text": "知识库讲义全面完善落地：清理错位/悬空历史条目、同步 2027 教材修订与知狐实操专题；重绘 8 张高清无水印矢量图（选择排序、二分查找过程、UML 用例与顺序图消息）；统一重点/难点徽章及注意事项卡片与四色图例一致；升级讲义检索居中摘要与相关性排序，并上线考点卡片「专练本考点」直达练习按钮"}, {"date": "2026-11-11", "text": "全考纲 232 篇三级讲义尾部统一上线「考向复习提示」与「高频易错陷阱」专属微质感卡片；章节考情说明解耦置顶，移除冗余标识；物理清理重复题目并优化三级节点关联"}, {"date": "2026-11-10", "text": "知识库二期全量升级：两本复习教程 PDF 正文、红/绿/黄三色重点标记、18 张表格与 431 张正向去水印配图 100% 无损收录，文末融合真题补充要点；题目关联全面切至考纲三级节点；公告改为仅在版本变动时提示"}, {"date": "2026-11-02", "text": "全考纲 232 篇三级结构化讲义首版发布；错题本新增「今日到期」间隔重复筛选；「我的」新增反馈处理进度；完成 C 语言与 229 道题型复核及 X9 未分类清零；通过公安联网备案"}, {"date": "2026-10-31", "text": "上线普通账号每日 200 道不同题作答额度（重做不重复计次，免限用户与管理员不受限，达上限可直接联系作者申请）"}, {"date": "2026-10-30", "text": "注册新增确认密码一致性校验；联系作者反馈改为选填描述；处理用户题目报错并修正争议题"}, {"date": "2026-10-29", "text": "随机组卷加入 100/50 分钟计时并与常规练习判分统一；清空历史改为归档；游客退出提示保存进度；处理 19 条题目反馈"}, {"date": "2026-10-28", "text": "知识点阅读器新增本节目录、阅读进度与随堂自测；清洗 C 语言代码类题目格式；新增站内公告、联系作者与题目报错入口"}, {"date": "2026-10-27", "text": "重构知识点为节级连续阅读器；新增邮箱归属验证、学习报告节级掌握度、错题筛选抽测与含解析打印；补齐 ICP 备案页脚与隐私/用户协议"}, {"date": "2026-10-26", "text": "支持一级章（80/40 题）与二级节（40 题）按考纲配比随机组卷；答题卡按题型分组；完成 85 组重复选择题去重"}, {"date": "2026-10-25", "text": "上线暖砂纸阅读主题与夜间模式；首页展示全站学习总进度与章节进度条；随机组卷优先抽取未做过的题"}, {"date": "2026-10-24", "text": "章节练习、错题本与做题历史支持按题型分类筛选与专项刷题；完成后端接口与权限加固"}, {"date": "2026-10-23", "text": "新增邮箱登录与找回密码、做题历史与错题复习；完成多轮题库质检、跨学科误挂清理与答案修正"}, {"date": "2026-10-22", "text": "完成知识点向考纲二级节的深层映射，并建立 1,876 条知识点与真题双向关联"}, {"date": "2026-10-21", "text": "知识点学习页首版上线（大纲树浏览、双向跳转、全库搜索、知识点掌握度）；上线刷题快速模式；完成 8,500+ 道题目章节归位与阿里云 HTTPS 部署"}, {"date": "2026-10-20", "text": "项目建站：采用 Vue 3 + Spring Boot 架构，按江苏计算机专转本考纲搭建课程 A/B 与技能一～六体系，上线章节刷题、错题本、收藏夹、随机组卷、AI 答疑与学习报告"}]$ann_hist$::jsonb,
       updated_at = NOW()
 WHERE id = 1;

